/**
 * Plain text, which is what most people read of this site.
 *
 * toPlainText feeds the homepage's Now preview, every meta description, the
 * feeds' summaries, the search index and its snippets. A mistake here does not
 * break a page; it quietly mangles a sentence in six places at once. Both of
 * these shipped:
 *
 * - Inline code was deleted, words and all. The Now template's instructions
 *   reached the homepage as "do not edit this file — add . Every Now entry…".
 * - Headings were flattened into the paragraph under them, so a Now entry —
 *   which is nothing but short headed sections — read "Working Shipping
 *   firmware for a sensor… Building ReMow, slowly…".
 */

import { strict as assert } from 'node:assert';
import { describe, it } from 'node:test';

import { toPlainText } from '../../src/lib/utils.ts';

describe('toPlainText', () => {
  it('keeps the words inside inline code', () => {
    assert.equal(
      toPlainText('add `content/now/2026-10.mdx` next month'),
      'add content/now/2026-10.mdx next month',
    );
  });

  it('does not let emphasis stripping eat the inside of code', () => {
    assert.equal(toPlainText('The trick was `duty_cycle`.'), 'The trick was duty_cycle.');
    assert.equal(toPlainText('`a*b*c` and *em*'), 'a*b*c and em');
  });

  it('ends a heading with a stop so it cannot run into the next sentence', () => {
    assert.equal(
      toPlainText('## Working\n\nShipping firmware.\n\n## Building\n\nReMow, slowly.'),
      'Working. Shipping firmware. Building. ReMow, slowly.',
    );
  });

  it('leaves a heading that already has punctuation alone', () => {
    assert.equal(
      toPlainText('## What happened?\n\nIt failed.'),
      'What happened? It failed.',
    );
    assert.equal(toPlainText('### Notes:\n\nOne.'), 'Notes: One.');
  });

  it('still drops fenced code, components, images and comments', () => {
    const mdx = [
      '{/* a note to myself */}',
      '<Figure src="x" alt="y" />',
      '![alt](img.jpg)',
      '```rust\nfn main() {}\n```',
      'A [link](https://example.com) stays as words.',
    ].join('\n\n');
    assert.equal(toPlainText(mdx), 'A link stays as words.');
  });
});
